// The library server end to end, against a temporary library and repos
// generated by the test (made-up people and messages). No network.

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { startServer } from '../src/server.js';
import { makeRepo, addCommits, tempDir, removeDir } from '@commit-wars/git-source/test-repo';

let srv, base, root;
const dirs = [];
const call = async (method, path, body, headers = {}) => {
  const res = await fetch(base + path, { method, headers: { ...(body !== undefined ? { 'content-type': 'application/json' } : {}), ...headers }, body: body !== undefined ? JSON.stringify(body) : undefined });
  const text = await res.text();
  let json = null; try { json = JSON.parse(text); } catch { /* not json */ }
  return { status: res.status, json, headers: res.headers };
};
const storyOf = async (c, s) => (await call('GET', '/api/library')).json.collections.find((x) => x.slug === c)?.stories.find((x) => x.slug === s);
async function settle(c, s, timeout = 20000) {
  const t0 = Date.now();
  for (;;) {
    const st = await storyOf(c, s);
    if (st && ['ready', 'error'].includes(st.status)) return st;
    if (Date.now() - t0 > timeout) throw new Error(`story ${c}/${s} stuck in ${st && st.status}`);
    await new Promise((r) => setTimeout(r, 60));
  }
}

beforeAll(async () => {
  root = tempDir('cw-lib-'); dirs.push(root);
  srv = await startServer({ port: 0, library: root, quiet: true });
  base = srv.url;
});
afterAll(async () => { await srv.close(); dirs.forEach(removeDir); });

describe('library server', () => {
  const repo = makeRepo({ n: 14, tagAt: { 7: 'v1.0.0' } }); dirs.push(repo);

  it('starts with an empty library', async () => {
    const r = await call('GET', '/api/library');
    expect(r.status).toBe(200);
    expect(r.json).toEqual({ collections: [], canManage: true });
  });

  it('creates a collection as a folder', async () => {
    const r = await call('POST', '/api/collections', { name: 'Open Source AI', description: 'tools' });
    expect(r.status).toBe(201);
    expect(r.json.collection).toMatchObject({ slug: 'open-source-ai', name: 'Open Source AI', stories: [] });
    expect(existsSync(join(root, 'open-source-ai', 'collection.json'))).toBe(true);
  });

  it('adds a story, clones and builds it, and serves the episode with an ETag', async () => {
    const r = await call('POST', '/api/collections/open-source-ai/stories', { url: repo, name: 'Demo Repo' });
    expect(r.status).toBe(202);
    expect(r.json.story).toMatchObject({ slug: 'demo-repo', status: 'queued' });
    expect(r.json.job.id).toBeTruthy();
    const st = await settle('open-source-ai', 'demo-repo');
    expect(st.error).toBeNull();
    expect(st).toMatchObject({ status: 'ready', commits: 14, hasEpisode: true });
    for (const f of ['story.json', 'history.json', 'episode.json']) expect(existsSync(join(root, 'open-source-ai', 'demo-repo', f))).toBe(true);
    expect(existsSync(join(root, 'open-source-ai', 'demo-repo', 'repo.git', 'HEAD'))).toBe(true);
    const ep = await call('GET', '/api/collections/open-source-ai/stories/demo-repo/episode');
    expect(ep.status).toBe(200);
    expect(ep.json.schemaVersion).toBe(2);
    expect(ep.json.summary.commits).toBe(14);
    const etag = ep.headers.get('etag');
    expect(etag).toBeTruthy();
    const again = await call('GET', '/api/collections/open-source-ai/stories/demo-repo/episode', undefined, { 'if-none-match': etag });
    expect(again.status).toBe(304);
  });

  it('updates: no rebuild without new commits, a rebuild with them', async () => {
    const before = await storyOf('open-source-ai', 'demo-repo');
    await call('POST', '/api/collections/open-source-ai/stories/demo-repo/update', {});
    let st = await settle('open-source-ai', 'demo-repo');
    await new Promise((r) => setTimeout(r, 200));
    st = await settle('open-source-ai', 'demo-repo');
    expect(st.builtAt).toBe(before.builtAt);
    expect(st.fetchedAt >= before.fetchedAt).toBe(true);
    addCommits(repo, { n: 3, from: 14 });
    const u = await call('POST', '/api/collections/open-source-ai/update', {});
    expect(u.status).toBe(202);
    await new Promise((r) => setTimeout(r, 100));
    st = await settle('open-source-ai', 'demo-repo');
    expect(st.commits).toBe(17);
    expect(st.builtAt).not.toBe(before.builtAt);
  });

  it('rebuilds on Update when the story engine has changed, even with no new commits', async () => {
    const file = join(root, 'open-source-ai', 'demo-repo', 'story.json');
    const { writeFileSync } = await import('node:fs');
    const st = JSON.parse(readFileSync(file, 'utf8'));
    writeFileSync(file, JSON.stringify({ ...st, engine: '0.0.1' }));
    const before = st.builtAt;
    await call('POST', '/api/collections/open-source-ai/stories/demo-repo/update', {});
    await new Promise((r) => setTimeout(r, 150));
    const after = await settle('open-source-ai', 'demo-repo');
    expect(after.builtAt).not.toBe(before);
    expect(JSON.parse(readFileSync(file, 'utf8')).engine).not.toBe('0.0.1');
  });
  it('renames and moves stories by moving their folders', async () => {
    await call('POST', '/api/collections', { name: 'Web' });
    let r = await call('PATCH', '/api/collections/open-source-ai/stories/demo-repo', { name: 'Demo Two' });
    expect(r.status).toBe(200);
    expect(r.json.story).toMatchObject({ slug: 'demo-two', collection: 'open-source-ai', name: 'Demo Two' });
    expect(existsSync(join(root, 'open-source-ai', 'demo-two', 'episode.json'))).toBe(true);
    expect(existsSync(join(root, 'open-source-ai', 'demo-repo'))).toBe(false);
    r = await call('PATCH', '/api/collections/open-source-ai/stories/demo-two', { collection: 'web' });
    expect(r.json.story).toMatchObject({ slug: 'demo-two', collection: 'web' });
    expect(existsSync(join(root, 'web', 'demo-two', 'repo.git'))).toBe(true);
    const web = JSON.parse(readFileSync(join(root, 'web', 'collection.json'), 'utf8'));
    expect(web.order).toEqual(['demo-two']);
  });

  it('renames a collection by renaming its folder', async () => {
    const r = await call('PATCH', '/api/collections/web', { name: 'Web Frameworks' });
    expect(r.json.collection.slug).toBe('web-frameworks');
    expect(existsSync(join(root, 'web-frameworks', 'demo-two', 'story.json'))).toBe(true);
  });

  it('asks before deleting, then removes the folder', async () => {
    let r = await call('DELETE', '/api/collections/web-frameworks/stories/demo-two');
    expect(r.status).toBe(409);
    expect(r.json.error).toMatch(/Confirm/);
    r = await call('DELETE', '/api/collections/web-frameworks/stories/demo-two?confirm=demo-two');
    expect(r.status).toBe(200);
    expect(existsSync(join(root, 'web-frameworks', 'demo-two'))).toBe(false);
    r = await call('DELETE', '/api/collections/web-frameworks');
    expect(r.status).toBe(200);
    expect(existsSync(join(root, 'web-frameworks'))).toBe(false);
  });

  it('reports build problems on the story in plain words', async () => {
    const tiny = makeRepo({ n: 3 }); dirs.push(tiny);
    await call('POST', '/api/collections/open-source-ai/stories', { url: tiny, name: 'Tiny' });
    const st = await settle('open-source-ai', 'tiny');
    expect(st.status).toBe('error');
    expect(st.error).toMatch(/at least 10/);
    const gone = await call('POST', '/api/collections/open-source-ai/stories', { url: 'file:///no/such/repo/here', name: 'Gone' });
    expect(gone.status).toBe(400);
    expect(gone.json.error).toMatch(/doesn't exist/);
  });

  it('rejects bad input and unknown places', async () => {
    expect((await call('POST', '/api/collections/open-source-ai/stories', { url: '--upload-pack=x' })).status).toBe(400);
    expect((await call('POST', '/api/collections', { name: '' })).json.error).toMatch(/name/);
    expect((await call('GET', '/api/collections/nope/stories/x/episode')).status).toBe(404);
    expect((await call('GET', '/api/collections/..%2F..%2Fetc/stories/passwd/episode')).status).toBe(404);
  });

  it('only accepts JSON writes from this machine\'s own pages', async () => {
    const plain = await fetch(base + '/api/collections', { method: 'POST', headers: { 'content-type': 'text/plain' }, body: '{"name":"x"}' });
    expect(plain.status).toBe(415);
    expect((await call('POST', '/api/collections', { name: 'x' }, { origin: 'https://evil.example' })).status).toBe(403);
    expect((await call('POST', '/api/collections', { name: 'x' }, { origin: 'http://127.0.0.1:5173' })).status).toBe(201);
  });

  it('streams job progress as server-sent events', async () => {
    const ac = new AbortController();
    const res = await fetch(base + '/api/events', { signal: ac.signal });
    expect(res.headers.get('content-type')).toMatch(/text\/event-stream/);
    const reader = res.body.getReader();
    const r2 = makeRepo({ n: 11 }); dirs.push(r2);
    await call('POST', '/api/collections/open-source-ai/stories', { url: r2, name: 'Streamed' });
    let text = '';
    const t0 = Date.now();
    while (!/event: job[\s\S]*"state":"done"/.test(text) && Date.now() - t0 < 15000) text += new TextDecoder().decode((await reader.read()).value || new Uint8Array());
    ac.abort();
    expect(text).toMatch(/event: job/);
    expect(text).toMatch(/"phase":"(cloning|building)"/);
    expect(text).toMatch(/"state":"done"/);
  });
});

describe('LAN mode: other machines can watch, only this machine can change', async () => {
  const { networkInterfaces } = await import('node:os');
  const lanIp = Object.values(networkInterfaces()).flat().find((a) => a && a.family === 'IPv4' && !a.internal)?.address;
  let lan, lanRoot;
  beforeAll(async () => {
    lanRoot = tempDir('cw-lan-'); dirs.push(lanRoot);
    lan = await startServer({ port: 0, library: lanRoot, lan: true, quiet: true });
  });
  afterAll(async () => { await lan.close(); });
  const at = (host) => `http://${host}:${lan.port}`;

  it('lets this machine manage', async () => {
    const r = await fetch(at('127.0.0.1') + '/api/collections', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name: 'Shared' }) });
    expect(r.status).toBe(201);
    const lib = await (await fetch(at('127.0.0.1') + '/api/library')).json();
    expect(lib.canManage).toBe(true);
  });
  it.skipIf(!lanIp)('lets another machine watch but not change anything', async () => {
    const lib = await (await fetch(at(lanIp) + '/api/library')).json();
    expect(lib.canManage).toBe(false);
    expect(lib.collections.map((c) => c.slug)).toEqual(['shared']);
    const add = await fetch(at(lanIp) + '/api/collections', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name: 'Nope' }) });
    expect(add.status).toBe(403);
    expect((await add.json()).error).toMatch(/only on the machine running the library/);
    const del = await fetch(at(lanIp) + '/api/collections/shared', { method: 'DELETE' });
    expect(del.status).toBe(403);
  });
  it.skipIf(!lanIp)('refuses names it does not know, so other websites cannot read the library', async () => {
    // fetch() won't send a custom Host header, so use http.request like a rebinding page would arrive
    const { request } = await import('node:http');
    const status = await new Promise((res, rej) => {
      const q = request({ host: lanIp, port: lan.port, path: '/api/library', headers: { host: `evil.example:${lan.port}` } }, (r) => { r.resume(); res(r.statusCode); });
      q.on('error', rej); q.end();
    });
    expect(status).toBe(403);
  });
  it('stays local-only without --lan', async () => {
    expect((await call('GET', '/api/library')).json.canManage).toBe(true);
    if (lanIp) await expect(fetch(`http://${lanIp}:${srv.port}/api/library`)).rejects.toThrow();
  });
});

describe('collection movies', async () => {
  let col, colRoot;
  const dirs2 = [];
  const api2 = async (method, path, body) => {
    const res = await fetch(col.url + path, { method, headers: body !== undefined ? { 'content-type': 'application/json' } : {}, body: body !== undefined ? JSON.stringify(body) : undefined });
    const text = await res.text(); let json = null; try { json = JSON.parse(text); } catch { /* not json */ }
    return { status: res.status, json };
  };
  const collectionReady = async (c, timeout = 30000) => {
    const t0 = Date.now();
    for (;;) {
      const lib = (await api2('GET', '/api/library')).json;
      const info = lib.collections.find((x) => x.slug === c);
      if (info && info.episode && ['ready', 'error'].includes(info.episode.status) && !info.stories.some((s) => ['queued', 'cloning', 'building'].includes(s.status))) return info;
      if (Date.now() - t0 > timeout) throw new Error(`collection ${c} not built: ${JSON.stringify(info && info.episode)}`);
      await new Promise((r) => setTimeout(r, 80));
    }
  };
  beforeAll(async () => {
    colRoot = tempDir('cw-col-'); dirs2.push(colRoot);
    col = await startServer({ port: 0, library: colRoot, quiet: true });
    const a = makeRepo({ n: 14 }); const b = makeRepo({ n: 12, start: '2024-02-01' }); dirs2.push(a, b);
    await api2('POST', '/api/collections', { name: 'Team' });
    await api2('POST', '/api/collections/team/stories', { url: a, name: 'Alpha' });
    await api2('POST', '/api/collections/team/stories', { url: b, name: 'Beta' });
  });
  afterAll(async () => { await col.close(); dirs2.forEach(removeDir); });

  it('builds one movie from all the stories in the collection', async () => {
    const info = await collectionReady('team');
    expect(info.episode).toMatchObject({ status: 'ready', commits: 26, repos: 2 });
    expect(existsSync(join(colRoot, 'team', 'collection-episode.json'))).toBe(true);
    const ep = (await api2('GET', '/api/collections/team/episode')).json;
    expect(ep.timeline.repos.map((r) => r.name)).toEqual(['Alpha', 'Beta']);
    const ada = ep.timeline.people.find((p) => p.names.includes('Ada Test'));
    const repos = new Set(ep.timeline.commits.filter((c) => ep.timeline.people[c[1]] === ada).map((c) => c[9]));
    expect([...repos].sort()).toEqual([0, 1]);
    expect(ep.timeline.people.filter((p) => p.names.includes('Ada Test'))).toHaveLength(1);
  });
  it('rebuilds when a story in it changes', async () => {
    const before = (await collectionReady('team')).episode.builtAt;
    await api2('PATCH', '/api/collections/team/stories/beta', { name: 'Beta Two' });
    await new Promise((r) => setTimeout(r, 150));
    const info = await collectionReady('team');
    expect(info.episode.builtAt).not.toBe(before);
    const ep = (await api2('GET', '/api/collections/team/episode')).json;
    expect(ep.timeline.repos.map((r) => r.name)).toEqual(['Alpha', 'Beta Two']);
  });
  it('merges two developers the owner says are the same, and separates them again', async () => {
    let ep = (await api2('GET', '/api/collections/team/episode')).json;
    const [a, b] = ep.timeline.people.filter((p) => !p.bot).map((p) => p.name);
    const r = await api2('POST', '/api/collections/team/people', { action: 'merge', names: [a, b] });
    expect(r.status).toBe(202);
    await new Promise((res) => setTimeout(res, 150));
    await collectionReady('team');
    ep = (await api2('GET', '/api/collections/team/episode')).json;
    const merged = ep.timeline.people.find((p) => p.name === a);
    expect(merged.emails.length).toBeGreaterThanOrEqual(2);
    expect(ep.timeline.people.some((p) => p.name === b)).toBe(false);
    const saved = JSON.parse(readFileSync(join(colRoot, 'team', 'collection.json'), 'utf8'));
    expect(saved.people.merge[0].name).toBe(a);
    await api2('POST', '/api/collections/team/people', { action: 'separate', name: a });
    await new Promise((res) => setTimeout(res, 150));
    await collectionReady('team');
    ep = (await api2('GET', '/api/collections/team/episode')).json;
    expect(ep.timeline.people.some((p) => p.name === b)).toBe(true);
  });
  it('explains an unknown developer', async () => {
    const r = await api2('POST', '/api/collections/team/people', { action: 'merge', names: ['Nobody', 'Ada'] });
    expect(r.status).toBe(400);
    expect(r.json.error).toMatch(/Nobody/);
  });
});
